class ProductionConfig(BaseConfig):
    BASE_URL = 'https://scout.nsn-rdnet.net'
    API_VERSION = 'v1'


class StagingConfig(BaseConfig):
    BASE_URL = 'https://staging.scout.wroclaw.nsn-rdnet.net'
    API_VERSION = 'v1'


class Config:
    CONFIG_TEMPLATE = {
        'endpoints': {},
        'data_pointers': {
            'testline_parameters': {},
            'testline_parameters_history': {}
        },
        'statuses': {},
        'consts': {}
    }

    def __init__(self, env):
        self.env_config = self._get_env_config(env)
        self.defaults = DefaultConfigValues()
        self.config = self._generate_config()

    @staticmethod
    def _get_env_config(env):
        env_config = BaseConfig()
        if env == 'production':
            env_config = ProductionConfig()
        elif env == 'staging':
            env_config = StagingConfig()
        return env_config

    def _generate_config(self):
        config = self.CONFIG_TEMPLATE
        config['endpoints'] = self._fill_endpoints()
        config['data_pointers']['testline_parameters'] = self._fill_testline_parameters_data_pointers()
        config['data_pointers']['testline_parameters_history'] = self._fill_testline_parameters_history_pointers()
        config['statuses'] = self._fill_statuses()
        config['memory_data'] = self._fill_memory_data()
        config['consts'] = self._fill_consts()
        return config

    def _fill_endpoints(self):
        endpoints = self.defaults.ENDPOINTS
        if self.env_config.ENDPOINTS:
            for k, v in self.env_config.ENDPOINTS.items():
                endpoints[k] = v
        return endpoints

    def _fill_consts(self):
        consts = self.defaults.CONSTS
        if self.env_config.CONSTS:
            for k, v in self.env_config.CONSTS.items():
                consts[k] = v
        return consts

    def _fill_testline_parameters_data_pointers(self):
        testline_parameters_data_pointers = self.defaults.TESTLINE_PARAMETERS_DATA_POINTERS
        if self.env_config.TESTLINE_PARAMETERS_DATA_POINTERS:
            for k, v in self.env_config.TESTLINE_PARAMETERS_DATA_POINTERS.items():
                testline_parameters_data_pointers[k] = v
        return testline_parameters_data_pointers

    def _fill_testline_parameters_history_pointers(self):
        testline_parameters_history_pointers = self.defaults.TESTLINE_PARAMETERS_HISTORY_POINTERS
        if self.env_config.TESTLINE_PARAMETERS_HISTORY_POINTERS:
            for k, v in self.env_config.TESTLINE_PARAMETERS_HISTORY_POINTERS.items():
                testline_parameters_history_pointers[k] = v
        return testline_parameters_history_pointers

    def _fill_statuses(self):
        statuses = self.defaults.STATUSES
        if self.env_config.STATUSES:
            for k, v in self.env_config.STATUSES.items():
                statuses[k] = v
        return statuses

    def _fill_memory_data(self):
        memory_data = self.defaults.MEMORY_DATA
        if self.env_config.MEMORY_DATA:
            for k, v in self.env_config.MEMORY_DATA.items():
                memory_data[k] = v
        return memory_data
